<style>
/* 제목 + 내부 링크 모두 덮어쓰기 (크기/두께/정렬/패딩) */
.post-title, .post-title a,
.article-title, .article-title a,
.page-title, .page-title a,
.post-header h1, .post-header h1 a,
h1.title, h1.title a {
  font-size: clamp(1.8rem, 6vw, 2.4rem) !important; /* 크기 ↑ */
  font-weight: 800 !important;                      /* 두껍게 */
  line-height: 1.1 !important;
  letter-spacing: -0.01em;
  text-align: left !important;
  padding-inline-start: clamp(0.5rem, 3vw, 2rem) !important; /* 왼쪽 패딩만 */
  margin: 0 0 .75rem 0 !important;
  text-decoration: none !important; /* 링크 밑줄 제거 (선택) */
}

/* 그라디언트 텍스트가 링크에도 확실히 적용되도록 */
.post-title a, .article-title a, .page-title a,
.post-header h1 a, h1.title a {
  display: inline-block; /* background-clip 적용 안정화 */
  background: linear-gradient(90deg, #06b6d4, #6366f1, #f43f5e);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent; color: transparent !important;
}
/* 1) .post-links 자체와 내부 요소의 padding 제거 */
.post-links,
.post-links ul,
.post-links li,
.post-links a{
  padding: 0 !important;
}

/* 2) (옵션) 간격이 gap/margin으로 들어온 경우도 무력화 */
.post-links{
  margin: 0 !important;      /* 위/아래 여백도 제거 */
  gap: 0 !important;         /* flex/grid gap 제거 */
  border: none !important;   /* 테두리로 보이는 경우 제거 */
  list-style: none !important;
}

/* 3) 제목 바로 아래 마진까지 없애기 */
.post-title + .post-links,
.article-title + .post-links,
.page-title + .post-links,
.post-header h1 + .post-links{
  margin-top: 0 !important;
}

/* 4) 테마 특이성 높이기(제목 래퍼 안에 있을 때) */
.post-header .post-links,
.article-header .post-links{
  padding: 0 !important;
  margin: 0 !important;
  gap: 0 !important;
}
</style>



